-- Бренды: узбекское описание, настоящие описания вместо шаблона,
-- латинские адреса вместо brand-6/brand-25, без дубля «CID LINES».
ALTER TABLE "Brand" ADD COLUMN "descriptionUz" TEXT;

-- Дубль появился из-за регистра; товары «CID LINES» теперь показываются
-- на странице «CID Lines» (сравнение без учёта регистра). Брендовых связей нет.
DELETE FROM "Brand" AS d WHERE d."name" = 'CID LINES' AND EXISTS (SELECT 1 FROM "Brand" k WHERE k."name" = 'CID Lines');

UPDATE "Brand" SET "slug" = 'avivak' WHERE "name" = 'АВИВАК' AND "slug" ~ '^brand-[0-9]+$' AND NOT EXISTS (SELECT 1 FROM "Brand" WHERE "slug" = 'avivak');
UPDATE "Brand" SET "slug" = 'npts-belagrogen' WHERE "name" = 'НПЦ БелАгроГен (Беларусь)' AND "slug" ~ '^brand-[0-9]+$' AND NOT EXISTS (SELECT 1 FROM "Brand" WHERE "slug" = 'npts-belagrogen');

-- Описание заменяется, только если оно пустое или шаблонное «… — производитель ветеринарной продукции.»
UPDATE "Brand" SET "description" = 'Bioveta a.s. — чешский производитель ветеринарных вакцин и препаратов. На VetHub: вакцины для птицы (Орнипест, Орниброн, Орнибур Интермедиат Плюс), КРС (Биобос Респи 4), лошадей (БиоЭквин ФТ) и кроликов (Песторин Мормикс), сыворотка Имулизин для телят, противомаститные шприцы Интрамар ДС и простагландиновый препарат Эстрофан.', "descriptionUz" = 'Bioveta a.s. — chexiyalik veterinariya vaksinalari va preparatlari ishlab chiqaruvchisi. VetHub da: parranda (Ornipest, Ornibron, Ornibur Intermediate Plus), qoramol (Biobos Respi 4), otlar (Bioequin FT) va quyonlar (Pestorin Mormyx) uchun vaksinalar, buzoqlar uchun Imulizin zardobi, Intramar DS mastitga qarshi shpritslari va Estrophan prostaglandin preparati.' WHERE "name" = 'Bioveta' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'CID LINES — бельгийский производитель средств гигиены и биобезопасности для животноводства. На VetHub: ультращелочное пенное моющее средство Кеносан и средство для очистки систем поения Сид 2000.', "descriptionUz" = 'CID LINES — chorvachilik uchun gigiena va biohimoya vositalari ishlab chiqaruvchi belgiyalik kompaniya. VetHub da: Kenosan ultra ishqoriy koʻpikli yuvish vositasi va sugʻorish tizimlarini tozalash uchun CID 2000.' WHERE "name" = 'CID Lines' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'Intracare — нидерландский производитель средств гигиены и ухода для животноводства. На VetHub: пенное моющее средство Intra Foamclenar и раствор Intra Aerosol на эфирных маслах мяты и эвкалипта — при респираторных болезнях и тепловом стрессе.', "descriptionUz" = 'Intracare — chorvachilik uchun gigiena va parvarish vositalari ishlab chiqaruvchi niderlandiyalik kompaniya. VetHub da: Intra Foamclenar koʻpikli yuvish vositasi va yalpiz hamda evkalipt efir moylari asosidagi Intra Aerosol eritmasi — respirator kasalliklar va issiqlik stressida.' WHERE "name" = 'Intracare' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'Kaesler Nutrition — немецкий производитель кормовых добавок для птицеводства. На VetHub — линейка LOVIT для выпаивания: витамины (AD3E Forte, E+Se, Amino, Granule BX), добавки для печени (Hepavent) и дыхания (Breeze), пробиотик LOVIT Probiotic и индикатор-стабилизатор воды LOVIT Blue C для вакцинации с водой.', "descriptionUz" = 'Kaesler Nutrition — parrandachilik uchun ozuqa qoʻshimchalari ishlab chiqaruvchi nemis kompaniyasi. VetHub da — ichimlik suvi bilan beriladigan LOVIT liniyasi: vitaminlar (AD3E Forte, E+Se, Amino, Granule BX), jigar (Hepavent) va nafas olish (Breeze) uchun qoʻshimchalar, LOVIT Probiotic probiotigi hamda suv bilan vaksinatsiya qilish uchun LOVIT Blue C suv indikatori-stabilizatori.' WHERE "name" = 'Kaesler Nutrition GmbH (Германия)' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'Qingdao Vland Animal Health Group — китайский производитель ветеринарных вакцин. На VetHub — вакцины VAvi для птицы: живые против болезни Ньюкасла (La Sota, Clone 30), инфекционного бронхита (H120, 793B-like) и бурсальной болезни (штамм MB), комбинированная NI-HH1, инактивированные ND(II+VII)+AI и NIEA с компонентом гриппа птиц H9.', "descriptionUz" = 'Qingdao Vland Animal Health Group — veterinariya vaksinalari ishlab chiqaruvchi xitoylik kompaniya. VetHub da — parrandalar uchun VAvi vaksinalari: Nyukasl kasalligi (La Sota, Clone 30), infeksion bronxit (H120, 793B-like) va bursal kasallik (MB shtammi)ga qarshi tirik vaksinalar, kombinatsiyalangan NI-HH1, H9 parranda grippi komponentli inaktivlangan ND(II+VII)+AI va NIEA.' WHERE "name" = 'Qingdao Vland Animal Health Group (Китай)' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'VORTEX — российский производитель профессиональных моющих и дезинфицирующих средств. На VetHub — средства для биозащиты птичников: щелочные и кислотные пенные моющие TANK, дезинфектанты ФОРБИЦИД Н, БИОТЕК СУПЕР и ДЕЗХЛОР, КСИЛАН для CIP-мойки и подкислитель воды СУПРАЦИД.', "descriptionUz" = 'VORTEX — professional yuvish va dezinfeksiya vositalari ishlab chiqaruvchi rossiyalik kompaniya. VetHub da — parrandaxonalar biohimoyasi uchun vositalar: TANK ishqoriy va kislotali koʻpikli yuvish vositalari, FORBICID H, BIOTEC SUPER va Dezxlor dezinfektantlari, CIP-yuvish uchun KSILAN va SUPRACID suv kislotalashtiruvchisi.' WHERE "name" = 'VORTEX (Россия)' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'НПП «АВИВАК» — российский производитель вакцин для птицеводства. На VetHub — живые вакцины против ньюкаслской болезни, инфекционного бронхита кур, инфекционной бурсальной болезни, ларинготрахеита и оспы птиц, а также инактивированная АВИВАК-ИБК+НБ+ССЯ-76.', "descriptionUz" = 'AVIVAK — parrandachilik uchun vaksinalar ishlab chiqaruvchi rossiyalik kompaniya. VetHub da — Nyukasl kasalligi, tovuqlarning yuqumli bronxiti, yuqumli bursal kasallik, laringotraxeit va parrandalar chechagiga qarshi tirik vaksinalar hamda inaktivlangan AVIVAK-IBK+NB+SSYA-76.' WHERE "name" = 'АВИВАК' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');
UPDATE "Brand" SET "description" = 'НПЦ «БелАгроГен» — белорусский производитель ветеринарных препаратов. На VetHub — антибактериальные препараты для птицы для приёма внутрь с водой: Тилмикофорс-О (тилмикозин), Респирофлор-О 300 (флорфеникол), Эксакон (энрофлоксацин + колистин) и Тилобаг (тилозин).', "descriptionUz" = 'BelAgroGen — veterinariya preparatlari ishlab chiqaruvchi belaruslik kompaniya. VetHub da — parrandalar uchun ichimlik suvi bilan beriladigan antibakterial preparatlar: Tilmicoforce-O (tilmikozin), Respiroflor-O 300 (florfenikol), Exakon (enrofloksatsin + kolistin) va Tylobagum (tilozin).' WHERE "name" = 'НПЦ БелАгроГен (Беларусь)' AND ("description" IS NULL OR "description" LIKE '% — производитель ветеринарной продукции.');

-- Узбекские названия категорий: официальное написание и буква ʻ, как на всём сайте.
UPDATE "Category" SET "nameUz" = 'Vaksinalar' WHERE "slug" = 'vaccines' AND "nameUz" = 'Vaktsinalar';
UPDATE "Category" SET "nameUz" = 'Ozuqa qoʻshimchalari' WHERE "slug" = 'feed-additives' AND "nameUz" = 'Ozuqa qo''shimchalari';
